import java.util.*;

class Solution {
    public int maxConsecutiveOnes(int[] nums) {
        int best = 0, current = 0;
        for (int value : nums) {
            if (value == 1) {
                current++;
                best = Math.max(best, current);
            } else {
                current = 0;
            }
        }
        return best;
    }
}
